pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, address caller, uint256 warpTime) public {
        // restrict to admissible domain: blockNum > 0, warpTime > old pastBlockTime,
        // and blockNum must satisfy block.number % 15 == 0 for the transfer path
        vm.assume(blockNum > 0);
        vm.assume(blockNum % 15 == 0);
        vm.assume(caller != address(0));
        // ensure warpTime is strictly greater than the current pastBlockTime (which starts at 0)
        vm.assume(warpTime > c.pastBlockTime());

        // set block number and timestamp
        vm.roll(blockNum);
        vm.warp(warpTime);

        // deal exactly 10 ether to caller (the required msg.value)
        vm.deal(caller, 10 ether);
        uint256 callerBalBefore = caller.balance;

        // call fallback with the required 10 ether
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success, "fallback call failed");

        // After the call, if block.number % 15 == 0 the entire contract balance should have been transferred.
        // The contract balance must be 0 (drained).
        assertTrue(address(c).balance == 0, "contract balance not drained");

        // The caller's balance should have increased by exactly the contract's pre-transfer balance,
        // which was the 10 ether just sent (since nobody else funded it).
        // The buggy version sends only 1 wei; the reference sends the full 10 ether.
        uint256 balanceAfter = caller.balance;
        assertTrue(balanceAfter == callerBalBefore + 10 ether, "caller did not receive full drained balance");
    }
}

