pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime) public {
        // Keep block number admissible
        bound(blockNum, 1, type(uint256).max - 1);
        // Keep warpTime admissible (pastBlockTime starts at 0)
        bound(warpTime, 1, type(uint256).max);

        // Setup: fund contract with 10 ether so fallback accepts
        vm.deal(address(c), 10 ether);
        // Set block timestamp
        vm.warp(warpTime);
        // Set block number
        vm.roll(blockNum);

        // Record caller balance and contract balance before fallback
        uint256 callerPrevBalance = address(this).balance;
        uint256 contractPrevBalance = address(c).balance;

        // Call fallback with exactly 10 ether
        vm.deal(address(this), 10 ether);
        c.f{value: 10 ether}();

        uint256 callerAfterBalance = address(this).balance;
        uint256 contractAfterBalance = address(c).balance;

        if (blockNum % 15 == 0) {
            // Transfer should have occurred: caller must gain entire contract balance (prev - 10 ether)
            uint256 expectedGain = contractPrevBalance;
            assertTrue(callerAfterBalance - callerPrevBalance == expectedGain);
        } else {
            // No transfer: contract should retain the 10 ether, caller balance unchanged (except spent 10 ether)
            assertTrue(contractAfterBalance == contractPrevBalance + 10 ether);
        }
    }
}

