pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 actorSeed) public {
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, 100 ether);
        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance;
        // set block.number to a multiple of 15 so the transfer triggers
        vm.roll(bound(actorSeed, 0, type(uint256).max - 15) / 15 * 15);
        vm.warp(block.timestamp + 1);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        uint256 callerAfter = actor.balance;
        uint256 contractAfter = address(c).balance;
        uint256 callerGain = callerAfter - callerBefore;
        // Property: caller's balance gain equals the contract's new balance plus the 10 ether sent (i.e., the full old contract balance)
        assertTrue(callerGain == contractAfter + 10 ether);
    }
}

