pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callerSeed) public {
        // callerSeed is used to derive a unique caller address via vm.addr,
        // ensuring different EOAs per fuzz run.
        address caller = vm.addr(callerSeed);
        // Admissible domain: callerSeed must map to a non-zero address, and
        // caller needs at least 10 ether to send.
        vm.assume(caller != address(0));
        vm.assume(callerSeed != 0);
        vm.deal(caller, 20 ether);

        // Record pastBlockTime before the call.
        uint256 beforePastBlockTime = c.pastBlockTime();

        // Ensure we are not at timestamp 0, so a correctly incrementing
        // timestamp is possible.
        vm.assume(block.timestamp > 0);

        // Advance time so the reference contract would accept the call.
        // The buggy one would also accept, but the property below catches
        // the missing check when we additionally call twice in the same block.
        vm.warp(block.timestamp + 1);

        // First call: should succeed on both reference and mutant when
        // timestamp is > pastBlockTime.
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        uint256 afterFirst = c.pastBlockTime();

        // Second call in the exact same block (no time advance).
        // The reference contract will revert because timestamp == pastBlockTime.
        // The mutant has no timestamp check, so it will succeed.
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // The general rule: after a successful fallback call, pastBlockTime
        // must have strictly increased compared to its value before the call
        // that succeeded. We check this by asserting that if the second call
        // succeeded, pastBlockTime after it is > the value after the first call.
        // On the reference, ok2 is false, so the assertion trivially holds.
        // On the buggy version, ok2 is true, but pastBlockTime is unchanged
        // (still afterFirst), so afterFirst == c.pastBlockTime(), violating strict
        // increase.
        assertTrue(!ok2 || c.pastBlockTime() > afterFirst);
    }
}

