pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockA, uint256 blockB, uint256 timeA, uint256 timeB) public {
        // Admissible domain: block numbers and timestamps must be realistic and distinct,
        // with blockB > blockA and timeB > timeA, both bounded to practical ranges.
        bound(blockA, 0, type(uint96).max);
        bound(blockB, blockA + 1, type(uint96).max);
        bound(timeA, 1, type(uint64).max);
        bound(timeB, timeA + 1, type(uint64).max);

        address actor = makeAddr("actor");
        vm.deal(actor, 100 ether);

        // First call in blockA at timeA
        vm.roll(blockA);
        vm.warp(timeA);
        vm.startPrank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        vm.stopPrank();
        require(ok1, "first call failed");

        uint256 contractBalAfterFirst = address(c).balance;

        // Second call in blockB at timeB
        vm.roll(blockB);
        vm.warp(timeB);
        vm.startPrank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        vm.stopPrank();
        require(ok2, "second call failed");

        uint256 actorBalanceAfterAll = actor.balance;
        uint256 expectedBalance;

        if (blockA % 15 == 0) {
            // First call transferred everything; actor would have gotten contractBalance back.
            // original actor had 100 ether, spent 10, received contract balance (which was at least 10).
            // After first call: actor = 100 - 10 + 10 = 100 (if no other ether in contract)
            // But there was 0 before, so after first transfer contract has 0.
            expectedBalance = 100 ether;
        } else {
            // First call did not transfer; actor spent 10, contract now has 10.
            expectedBalance = 90 ether;
        }

        // After second call, independent of whether second triggers a transfer,
        // actor's balance should be same as expectedBalance minus the 10 ether spent,
        // plus any transfer from the second call.
        // However, if first call transferred but race condition allows re-extraction,
        // actor could end up with more than expected.
        // We assert that actorBalanceAfterAll is exactly what the correct contract would give.
        // Correct behavior: after first call contract balance is either 0 (if transferred) or 10 (if not).
        // Second call adds 10, possibly transfers everything.
        uint256 correctFinalBalance;
        if (blockB % 15 == 0) {
            if (blockA % 15 == 0) {
                // contractBalAfterFirst = 0; second adds 10, transfers 10.
                correctFinalBalance = 100 ether - 10 ether + 10 ether; // 100
            } else {
                // contractBalAfterFirst = 10; second adds 10 => 20, transfers 20.
                correctFinalBalance = 90 ether - 10 ether + 20 ether; // 100
            }
        } else {
            if (blockA % 15 == 0) {
                // contractBalAfterFirst = 0; second adds 10, no transfer.
                correctFinalBalance = 100 ether - 10 ether; // 90
            } else {
                // contractBalAfterFirst = 10; second adds 10, no transfer.
                correctFinalBalance = 90 ether - 10 ether; // 80
            }
        }

        assertEq(actorBalanceAfterAll, correctFinalBalance, "balance mismatch");
    }
}

