pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 block1, uint256 block2) public {
        // admissible domain: distinct blocks; block1 % 15 != 0, block2 % 15 == 0
        vm.assume(block1 != block2);
        vm.assume(block1 % 15 != 0);
        vm.assume(block2 % 15 == 0);
        // prepare caller with 20 ether
        address caller = address(0x1234);
        vm.deal(caller, 20 ether);
        // first call: block1, no transfer
        vm.roll(block1);
        vm.prank(caller);
        c.fallback{value: 10 ether}();
        uint256 balBeforeSecond = address(c).balance;
        // second call: block2, should transfer but at most its own 10 ether
        vm.roll(block2);
        vm.prank(caller);
        c.fallback{value: 10 ether}();
        uint256 balAfterSecond = address(c).balance;
        // If no other transfers occurred, second call should not drain more than the 10 ether it brought
        // after second call, contract balance should be at least balBeforeSecond (the original balance)
        // because the transfer in block2 should send at most the contract balance before block2
        assertTrue(balAfterSecond >= balBeforeSecond);
    }
}

