pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 warpTime, uint256 callValue) public {
        // Ensure blockNumber and timestamp are positive and within a reasonable range.
        vm.assume(blockNum > 0);
        vm.assume(blockNum < type(uint64).max);
        vm.assume(warpTime > 0);
        // callValue must be exactly 10 ether to pass the require in fallback.
        vm.assume(callValue == 10 ether);

        // Set block number and timestamp.
        vm.roll(blockNum);
        vm.warp(warpTime);

        // Prepare sender with sufficient ether.
        address sender = address(0x1234);
        vm.deal(sender, 100 ether);

        // Make two fallback calls to satisfy the pastBlockTime constraint.
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        // Check that contract is still alive (not selfdestructed).
        // If selfdestructed, address(c).balance is zero and calls will fail.
        // We check by reading c's public state and balance.
        assertTrue(address(c).balance >= 0 && c.pastBlockTime() > 0);
    }
}

