pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber) public {
        vm.assume(blockNumber > 0);
        vm.roll(blockNumber);
        vm.warp(blockNumber);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 10 ether}("");
        assertTrue(success);
        bool ok;
        try c.fallback() { ok = false; } catch { ok = true; }
        // If the contract selfdestructed, c.fallback() will revert because there is no code.
        // The reference never selfdestructs, so c.fallback() never reverts for this reason.
        // The mutant selfdestructs when block.number % 15 == 0, causing a revert on subsequent call.
        if (blockNumber % 15 == 0) {
            assertTrue(ok);
        } else {
            assertTrue(!ok);
        }
    }
}

